import numpy as np, json
x=np.load('fit1.npy'); XL,mq,kiv,mp=np.exp(x)
sub={
 "params":{"XL":float(XL),"mq":float(mq),"kiv":float(kiv),"mp":float(mp),"TPf":0.01,"TQf":0.01,"TVf":0.01,"w0":2*np.pi*60},
 "defs":{
   "E0":"V0*sqrt((1+XL*Q0/V0**2)**2+(XL*P0/V0**2)**2)",
   "d0":"theta0+atan2(XL*P0/V0**2, 1+XL*Q0/V0**2)",
   "Ei":"xv",
   "Pe":"V*Ei*sin(delta-theta)/XL",
   "Qe":"(Ei*V*cos(delta-theta)-V**2)/XL",
   "Vcmd":"Vset+mq*(Q0-Qm)"
 },
 "states":{
   "Pm":{"rhs":"(Pe-Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Qe-Qm)/TQf","init":"Q0"},
   "Vm":{"rhs":"(V-Vm)/TVf","init":"V0"},
   "delta":{"rhs":"w0*mp*(P0-Pm)","init":"d0"},
   "xv":{"rhs":"kiv*(Vcmd-Vm)","init":"E0"}
 },
 "outputs":{"P":"Pe","Q":"Qe"}
}
json.dump(sub,open('submission.json','w'),indent=1)
print(open('submission.json').read()[:300])
